// Schedule-driven switchover of positionFeeFactor for RWA markets. See README.
//
// Switch instants come from a schedule file generated by the risk oracle, so holidays,
// early closes and DST are data rather than rules here.
//
// Level-triggered: each run switches only the markets whose recorded state differs from
// what the schedule says now, and records a market only once its switch succeeded.
//
// Ticks are serialised by `flock -n` in the crontab entry, not here — the kernel
// releases that on any exit, a pid file does not.
//
//   node scripts/switchover/runScheduled.js [--dry-run] [--schedule <path>]

const { execFileSync } = require("child_process");
const dotenv = require("dotenv");
const fs = require("fs");
const path = require("path");

const SWITCHOVER_DIR = __dirname;
const REPO_DIR = path.join(SWITCHOVER_DIR, "..", "..");

dotenv.config({ path: path.join(REPO_DIR, ".env") });

const { codeBlock, sendTelegram, pingHealthcheck } = require("../monitor/utils");
const MARKETS = require("./markets");

const STATE_DIR = path.join(SWITCHOVER_DIR, "state");
const LOG_DIR = path.join(REPO_DIR, "logs", "switchover");
const LOG_FILE = path.join(LOG_DIR, "run_scheduled.log");
const SWITCHOVER_ENV_FILE = path.join(SWITCHOVER_DIR, "switchover.env");
const HARDHAT_SCRIPT = "scripts/updateMarketConfig.ts";
const RUN_TIMEOUT_MS = 3 * 60 * 1000;
const HORIZON_WARN_DAYS = 14;
const MAX_LOG_LINES = 10000;
const REASON_MAX = 300; // keep the alert header well inside Telegram's 4096 limit

// hardhat prints this when the chain already holds the target values — a success.
const NO_CHANGES = "no changes to apply";

function usage() {
  process.stderr.write("usage: node scripts/switchover/runScheduled.js [--dry-run] [--schedule <path>]\n");
}

// To a file as well as stdout: cron stdout goes to local mail at best.
function log(msg) {
  const line = `${new Date().toISOString()} [switchover] ${msg}`;
  process.stdout.write(line + "\n");
  try {
    fs.appendFileSync(LOG_FILE, line + "\n");
  } catch {
    /* never let logging stop a switch */
  }
}

function rotateLog() {
  try {
    const lines = fs.readFileSync(LOG_FILE, "utf8").split("\n");
    if (lines.length > MAX_LOG_LINES) {
      fs.writeFileSync(LOG_FILE, lines.slice(-MAX_LOG_LINES).join("\n"));
    }
  } catch {
    /* nothing to rotate */
  }
}

function parseArgs(argv) {
  const opts = {
    dryRun: false,
    schedule: process.env.SWITCHOVER_SCHEDULE_FILE || path.join(SWITCHOVER_DIR, "schedule.txt"),
  };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--dry-run") opts.dryRun = true;
    else if (arg === "--schedule") {
      if (i + 1 >= argv.length) return null;
      opts.schedule = argv[++i];
    } else if (arg.startsWith("--schedule=")) opts.schedule = arg.slice("--schedule=".length);
    else return null;
  }
  return opts;
}

// WRITE/CLI make the hardhat script non-interactive and actually send; INCLUDE_* pick
// the parameter groups. The file is also sourced from a shell, so values still carrying
// `${...}` are skipped rather than passed through literally.
function loadSwitchoverEnv() {
  const parsed = dotenv.parse(fs.readFileSync(SWITCHOVER_ENV_FILE));
  const out = {};
  for (const [key, value] of Object.entries(parsed)) {
    if (!value.includes("${")) out[key] = value;
  }
  return out;
}

const TG_TOKEN = process.env.TELEGRAM_BOT_TOKEN;
const TG_CHAT = process.env.TELEGRAM_CHAT_ID;
const TG_ENABLED = process.env.SWITCHOVER_TG_MESSAGES === "true";

// Telegram's legacy Markdown 400s the whole message on an unbalanced * _ [ ] or
// backtick, so anything going outside a code block is stripped and bounded.
function plain(text, max = REASON_MAX) {
  const stripped = String(text)
    .replace(/[*_[\]`]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return stripped.length > max ? stripped.slice(0, max) + "…" : stripped;
}

async function notify(text, { silent = false } = {}) {
  if (!TG_ENABLED) {
    log(`[telegram off] ${text}`);
    return true;
  }
  try {
    await sendTelegram(TG_TOKEN, TG_CHAT, text, { silent });
    return true;
  } catch (e) {
    log(`telegram delivery failed: ${plain(e && e.message ? e.message : e)}`);
    return false;
  }
}

// One message a day for conditions that persist across ticks. The stamp is written only
// after delivery, so a network blip does not swallow the alert for the day.
async function notifyDaily(key, text, dryRun) {
  const stamp = path.join(STATE_DIR, `.notified_${key}_${new Date().toISOString().slice(0, 10)}`);
  if (fs.existsSync(stamp)) return;
  if (dryRun) {
    log(`[dry-run] ${text}`);
    return;
  }
  if (await notify(text)) {
    fs.writeFileSync(stamp, "");
    for (const f of fs.readdirSync(STATE_DIR)) {
      if (f.startsWith(`.notified_${key}_`) && path.join(STATE_DIR, f) !== stamp) {
        fs.rmSync(path.join(STATE_DIR, f), { force: true });
      }
    }
  }
}

// Fixed-width UTC, so string order is chronological. Rows are assumed to be in file
// order per calendar, which the generator guarantees.
function nowIso() {
  return new Date().toISOString().slice(0, 16) + "Z";
}

function parseSchedule(file) {
  const rows = [];
  const headers = new Map();
  const unknownKinds = new Set();
  for (const raw of fs.readFileSync(file, "utf8").split("\n")) {
    const line = raw.replace(/\r$/, "").trim();
    if (!line) continue;
    if (line.startsWith("#")) {
      // "# NYSE: SPCX/USD [WETH-USDC], ... (open delay 15min)" — the oracle's own market
      // list for that calendar, used below to catch ones this runner does not know.
      const m = line.match(/^#\s*(\w+):\s*(.+?)(?:\s*\(open delay.*)?$/);
      if (m) {
        headers.set(
          m[1],
          m[2]
            .split(",")
            .map((s) => s.trim().split("/")[0])
            .filter(Boolean)
        );
      }
      continue;
    }
    const [calendar, kind, at] = line.split(/\s+/);
    if (!calendar || !kind || !at) continue;
    if (kind !== "open" && kind !== "close") {
      // Not dropped silently: a new kind from the generator would otherwise leave the
      // market on a state the schedule has already ended.
      unknownKinds.add(`${calendar}:${kind}`);
      continue;
    }
    rows.push({ calendar, kind, at });
  }
  return { rows, headers, unknownKinds };
}

function stateFile(network, symbol) {
  return path.join(STATE_DIR, `${network}_${symbol}.state`);
}

function readState(network, symbol) {
  try {
    const value = fs.readFileSync(stateFile(network, symbol), "utf8").trim();
    return value === "onHours" || value === "offHours" ? value : null;
  } catch {
    return null;
  }
}

// temp + rename: a half-written file would read back as "first run" and skip a switch.
function writeState(network, symbol, value) {
  const target = stateFile(network, symbol);
  const tmp = `${target}.tmp`;
  fs.writeFileSync(tmp, value);
  fs.renameSync(tmp, target);
}

function applyMarket(network, entry, desired, switchoverEnv) {
  const env = {
    ...process.env,
    ...switchoverEnv,
    MARKET: entry.market,
    MARKET_STATE: desired,
    // Always explicit — inherited, it would narrow a market meant to write everything.
    SWITCHOVER_ONLY: entry.switchoverOnly ? "true" : "false",
  };

  let stdout = "";
  let failure = null;
  try {
    stdout = execFileSync("npx", ["--no-install", "hardhat", "run", HARDHAT_SCRIPT, "--network", network], {
      encoding: "utf8",
      env,
      timeout: RUN_TIMEOUT_MS,
      maxBuffer: 50 * 1024 * 1024,
      cwd: REPO_DIR,
    });
  } catch (e) {
    stdout = `${e.stdout || ""}${e.stderr || ""}`;
    failure = e.code === "ETIMEDOUT" ? `timed out after ${RUN_TIMEOUT_MS / 1000}s` : String(e.message || e);
  }

  // Scanned whether or not the process exited cleanly: hardhat can send the transaction
  // and then die, and calling that a failure would retry forever against a done chain.
  const hash = [...stdout.matchAll(/tx sent:\s*(\S+)/g)].pop();
  if (hash) return { ok: true, output: stdout, txHash: hash[1] };
  if (stdout.includes(NO_CHANGES)) return { ok: true, output: stdout, noChanges: true };
  return { ok: false, output: stdout, reason: failure || "no transaction was sent" };
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (!opts) {
    usage();
    process.exit(2);
  }

  fs.mkdirSync(STATE_DIR, { recursive: true });
  fs.mkdirSync(LOG_DIR, { recursive: true });

  if (TG_ENABLED && (!TG_TOKEN || !TG_CHAT)) {
    log("FATAL SWITCHOVER_TG_MESSAGES=true but TELEGRAM_BOT_TOKEN/TELEGRAM_CHAT_ID are unset");
    process.exit(1);
  }

  let switchoverEnv;
  try {
    switchoverEnv = loadSwitchoverEnv();
  } catch (e) {
    log(`FATAL cannot read switchover.env: ${plain(e && e.message ? e.message : e)}`);
    await notifyDaily("noenv", `*switchover*: cannot read \`switchover.env\` — no market can be switched`, opts.dryRun);
    process.exit(1);
  }
  if (switchoverEnv.WRITE !== "true" || switchoverEnv.CLI !== "true") {
    log("FATAL switchover.env must set WRITE=true and CLI=true");
    await notifyDaily(
      "badenv",
      `*switchover*: \`switchover.env\` lacks WRITE/CLI — switches would be read-only`,
      opts.dryRun
    );
    process.exit(1);
  }

  let schedule;
  try {
    schedule = parseSchedule(opts.schedule);
  } catch (e) {
    // Readability, not existence: a root-owned file passes existsSync and throws here.
    log(`FATAL cannot read schedule at ${opts.schedule}: ${plain(e && e.message ? e.message : e)}`);
    await notifyDaily(
      "noschedule",
      `*switchover*: cannot read the schedule at \`${opts.schedule}\` — no market is being switched`,
      opts.dryRun
    );
    process.exit(1);
  }

  const { rows, headers, unknownKinds } = schedule;
  for (const entry of unknownKinds) {
    const [calendar, kind] = entry.split(":");
    await notifyDaily(
      `kind_${calendar}`,
      `*switchover*: unknown transition kind \`${kind}\` for \`${calendar}\` in the schedule — rows are being ignored`,
      opts.dryRun
    );
  }

  const now = nowIso();
  let switched = 0;
  let failed = 0;
  let frozen = 0;

  for (const [network, calendars] of Object.entries(MARKETS)) {
    for (const [calendar, entries] of Object.entries(calendars)) {
      const forCalendar = rows.filter((r) => r.calendar === calendar);
      if (forCalendar.length === 0) {
        frozen++;
        log(`FROZEN ${network}/${calendar} — calendar absent from schedule`);
        await notifyDaily(
          `nocal_${calendar}`,
          `*switchover*: \`${calendar}\` has no rows in the schedule — its markets are frozen`,
          opts.dryRun
        );
        continue;
      }

      // Both bounds matter: past the end the file has run out, before the start it does
      // not cover now and inferring a state from a future transition would switch on the spot.
      const first = forCalendar[0].at;
      const last = forCalendar[forCalendar.length - 1].at;
      if (now > last) {
        frozen++;
        log(`FROZEN ${network}/${calendar} horizon exhausted (last ${last})`);
        await notifyDaily(
          `horizon_${calendar}`,
          `*switchover*: \`${calendar}\` schedule ran out at \`${last}\` — regenerate it, its markets are frozen`,
          opts.dryRun
        );
        continue;
      }
      if (first > now) {
        frozen++;
        log(`FROZEN ${network}/${calendar} schedule starts in the future (${first})`);
        await notifyDaily(
          `future_${calendar}`,
          `*switchover*: \`${calendar}\` schedule starts at \`${first}\`, after now — regenerate with an earlier --start`,
          opts.dryRun
        );
        continue;
      }
      const daysLeft = Math.floor((Date.parse(last) - Date.now()) / 86400000);
      if (daysLeft < HORIZON_WARN_DAYS) {
        await notifyDaily(
          `horizonsoon_${calendar}`,
          `*switchover*: \`${calendar}\` schedule ends \`${last}\` (${daysLeft} days left) — regenerate it`,
          opts.dryRun
        );
      }

      // A market the oracle switches but this runner does not map would keep its fee.
      const known = new Set(Object.values(MARKETS).flatMap((c) => (c[calendar] || []).map((e) => e.symbol)));
      const listed = headers.get(calendar);
      if (!listed) {
        await notifyDaily(
          `header_${calendar}`,
          `*switchover*: no header line for \`${calendar}\` in the schedule — cannot check for unmapped markets`,
          opts.dryRun
        );
      } else {
        for (const symbol of listed) {
          if (!known.has(symbol)) {
            await notifyDaily(
              `unmapped_${symbol}`,
              `*switchover*: oracle lists \`${symbol}\` on \`${calendar}\`, but this runner has no mapping for it`,
              opts.dryRun
            );
          }
        }
      }

      const transition = forCalendar.filter((r) => r.at <= now).pop();
      const desired = transition.kind === "open" ? "onHours" : "offHours";

      for (const entry of entries) {
        const current = readState(network, entry.symbol);

        if (current === null) {
          // First run: record where the schedule says we are without touching the chain.
          // Loud on purpose — the one message that asks for a human.
          if (opts.dryRun) {
            log(`[dry-run] would seed ${network}/${entry.symbol} as ${desired}`);
            continue;
          }
          writeState(network, entry.symbol, desired);
          log(`SEED ${network}/${entry.symbol} -> ${desired} (from ${transition.at})`);
          await notify(
            `*switchover*: seeded \`${network}/${entry.symbol}\` as *${desired}* (schedule \`${transition.at}\`). No transaction was sent — verify the on-chain state once.`
          );
          continue;
        }

        if (current === desired) continue;

        if (opts.dryRun) {
          log(`[dry-run] would switch ${network}/${entry.symbol} ${current} -> ${desired}`);
          continue;
        }

        log(`SWITCH ${network}/${entry.symbol} ${current} -> ${desired} (transition ${transition.at})`);
        const res = applyMarket(network, entry, desired, switchoverEnv);
        log(`hardhat output for ${network}/${entry.symbol}:\n${res.output.trim()}`);

        if (res.ok) {
          writeState(network, entry.symbol, desired);
          switched++;
          const detail = res.noChanges ? "already on-chain" : `tx: \`${res.txHash}\``;
          // Silent: routine successes would train everyone to mute the channel.
          await notify(`*switchover*: \`${network}/${entry.symbol}\` -> *${desired}* (${detail})`, { silent: true });
        } else {
          failed++;
          log(`FAILED ${network}/${entry.symbol} -> ${desired}: ${res.reason}; state left at ${current} for retry`);
          // Throttled: the retry reproduces the same failure every minute.
          await notifyDaily(
            `fail_${network}_${entry.symbol}`,
            `*switchover*: \`${network}/${entry.symbol}\` -> ${desired} failed (${plain(res.reason)})\n${codeBlock(
              res.output.slice(-1000)
            )}`,
            opts.dryRun
          );
        }
      }
    }
  }

  if (switched || failed || frozen) log(`done: ${switched} switched, ${failed} failed, ${frozen} calendars frozen`);
  if (failed || frozen) process.exitCode = 1;

  // A frozen calendar counts as broken: its markets are stuck while the oracle keeps
  // moving, which is what the watchdog is for.
  if (!failed && !frozen && process.env.SWITCHOVER_HEALTHCHECK_URL && !opts.dryRun) {
    await pingHealthcheck(process.env.SWITCHOVER_HEALTHCHECK_URL, (m) => log(m));
  }
  rotateLog();
}

main().catch(async (e) => {
  const detail = plain(e && e.stack ? e.stack : e, 500);
  log(`FATAL unhandled error: ${detail}`);
  try {
    await notify(`*switchover*: runner crashed — ${detail}`);
  } catch {
    /* already logged */
  }
  process.exit(1);
});
